/** inhale 4 s, exhale 6 s: about six calm breaths a minute */
export function Breathing() {
  const [phase, setPhase] = useState<'in' | 'out'>('out');
  useEffect(() => {
    let t: number;
    const step = (p: 'in' | 'out') => {
      setPhase(p);
