import { useEffect, useState } from 'react';

/** inhale 4 s, exhale 6 s: about six calm breaths a minute */
export function Breathing() {
  const [phase, setPhase] = useState<'in' | 'out'>('out');
  useEffect(() => {
    let t: number;
    const step = (p: 'in' | 'out') => {
      setPhase(p);
      t = window.setTimeout(() => step(p === 'in' ? 'out' : 'in'), p === 'in' ? 4000 : 6000);
    };
    t = window.setTimeout(() => step('in'), 400);
    return () => window.clearTimeout(t);
  }, []);
  return (
    <div className={`breath ${phase}`} aria-hidden="true">
      <div className="breath-ring" />
      <span className="breath-label">{phase === 'in' ? 'Breathe in' : 'Breathe out'}</span>
    </div>
  );
}

import { X } from 'lucide-react';
import { useApp } from '../../state/store';

export function Toasts() {
  const toasts = useApp((s) => s.toasts);
  const dismiss = useApp((s) => s.dismissToast);
  return (
    <div className="toasts" role="status" aria-live="polite">
      {toasts.map((t) => (
        <div key={t.id} className="toast glass">
          <span>{t.text}</span>
          <span className="inline">
            {t.action && (
              <button className="btn" onClick={t.action.run}>
                {t.action.label}
              </button>
            )}
            <button className="icon-btn" onClick={() => dismiss(t.id)} aria-label="Dismiss">
              <X aria-hidden="true" />
            </button>
          </span>
        </div>
      ))}
    </div>
  );
}

import { Component, type ReactNode } from 'react';

export class ErrorBoundary extends Component<{ children: ReactNode }, { error: Error | null }> {
  state = { error: null as Error | null };
  static getDerivedStateFromError(error: Error) {
    return { error };
  }
  componentDidCatch(error: Error) {
    console.error('Seedsong error:', error);
  }
  render() {
    if (!this.state.error) return this.props.children;
    return (
      <main className="error-screen">
        <div style={{ display: 'grid', gap: 16, justifyItems: 'center', maxWidth: 420 }}>
          <h1 style={{ fontFamily: 'var(--font-display)', fontWeight: 400, margin: 0 }}>Something went quiet.</h1>
          <p className="muted">The garden hit a snag. Your settings are saved, so replanting picks up where you were.</p>
          <button className="btn btn-primary" onClick={() => location.reload()}>
            Replant
          </button>
        </div>
      </main>
    );
  }
}

