const { useApp } = await import('/src/state/store.ts');
const { renderScore } = await import('/src/export/offline.ts');
const { encodeWav, measure, toDb, parseWav } = await import('/src/export/wav.ts');
const { scoreToMidi } = await import('/src/export/midi.ts');
const s = useApp.getState();
const t0 = performance.now();
const buf = await renderScore(s.score, s.seed, { ambience: s.settings.ambience, withAmbience: true });
const renderMs = performance.now() - t0;
const ch = [buf.getChannelData(0), buf.getChannelData(1)];
const raw = measure(ch);
// loudness profile per 10 s window (RMS dBFS) to find silences
const sr = buf.sampleRate, win = sr * 10, prof = [];
for (let i = 0; i < ch[0].length; i += win) { let sum = 0, n = 0; for (let j = i; j < Math.min(i + win, ch[0].length); j++) { sum += ch[0][j] ** 2 + ch[1][j] ** 2; n += 2; } prof.push(Math.round(toDb(Math.sqrt(sum / n)))); }
const bytes = encodeWav({ sampleRate: sr, channels: ch }, { bitDepth: 16, normalizeDb: -1, fadeOut: 3, info: { INAM: 'test', ICMT: s.shareUrl() } });
const parsed = parseWav(bytes);
const midi = scoreToMidi(s.score, 'test');
({ renderSeconds: (renderMs / 1000).toFixed(1), songSeconds: buf.duration.toFixed(1), rawPeakDb: toDb(raw.peak).toFixed(2), rawRmsDb: toDb(raw.rms).toFixed(1), wavMB: (bytes.length / 1e6).toFixed(1), parsed: { ...parsed, info: Object.keys(parsed.info) }, midiBytes: midi.length, rmsPer10s: prof.join(' ') })

