import { expect, type Page } from '@playwright/test';

export function collectErrors(page: Page): string[] {
  const errors: string[] = [];
  page.on('console', (m) => {
    if (m.type() === 'error') errors.push(m.text());
  });
  page.on('pageerror', (e) => errors.push(String(e)));
  return errors;
}

export async function begin(page: Page) {
  await page.goto('/');
  const button = page.getByRole('button', { name: 'Begin' });
  await expect(button).toBeVisible();
  await button.click();
  await expect(page.getByRole('button', { name: /Pause \(Space\)/ })).toBeVisible();
}
EOF
cat > tests/e2e/smoke.spec.ts <<'EOF'
import { expect, test } from '@playwright/test';
import { begin, collectErrors } from './helpers';

test('landing → Begin → the song plays and the tree grows, with no console errors', async ({ page }) => {
  const errors = collectErrors(page);
  await page.goto('/');
  await expect(page.getByRole('heading', { name: 'Seedsong' })).toBeVisible();
  await expect(page.getByText('Best with headphones')).toBeVisible();
  await expect(page.getByRole('button', { name: 'Begin' })).toBeFocused();
  await begin(page);
  await page.waitForTimeout(3500);
  const label = await page.getByRole('img').first().getAttribute('aria-label');
  expect(label).toMatch(/branches, \d+ levels deep, playing in/);
  const pos = page.getByRole('slider', { name: /Position in the song/ });
  const value = Number(await pos.getAttribute('aria-valuenow'));
  expect(value).toBeGreaterThanOrEqual(1);
  expect(errors).toEqual([]);
});

test('keyboard: shortcuts change mood, mode and seed', async ({ page }) => {
  await begin(page);
  await page.keyboard.press('3');
  await expect(page.getByRole('radio', { name: 'Deep Ocean' })).toHaveAttribute('aria-checked', 'true');
  await page.keyboard.press('w');
  await expect(page.getByRole('radio', { name: /Bloom/ })).toHaveAttribute('aria-checked', 'true');
  const sub = page.locator('.brand-sub');
  const before = await sub.textContent();
  await page.keyboard.press('n');
  await expect(sub).not.toHaveText(before ?? '');
  await page.keyboard.press('l');
  await expect(page.getByRole('complementary', { name: 'Recursion lens' })).toBeVisible();
});
EOF
cat > tests/e2e/export.spec.ts <<'EOF'
import { readFileSync } from 'node:fs';
import { expect, test } from '@playwright/test';
import { begin } from './helpers';

test('exports a non-silent WAV rendered offline', async ({ page }) => {
  await begin(page);
  // a short tree keeps the test quick
  await page.getByRole('button', { name: 'Shape your garden' }).click();
  const depth = page.getByRole('slider', { name: 'Depth' });
  await depth.fill('4');
  await page.waitForTimeout(800);
  await page.keyboard.press('Escape');
  await page.getByRole('button', { name: /Keep this song/ }).click();
  const downloadPromise = page.waitForEvent('download', { timeout: 110_000 });
  await page.getByRole('button', { name: 'Download WAV' }).click();
  const download = await downloadPromise;
  expect(download.suggestedFilename()).toMatch(/^seedsong_dawn_.+\.wav$/);
  const file = await download.path();
  const bytes = readFileSync(file);
  expect(bytes.length).toBeGreaterThan(200_000);
  expect(bytes.subarray(0, 4).toString('ascii')).toBe('RIFF');
  // RMS of the 16-bit samples after the header
  const dataAt = bytes.indexOf('data');
  let sum = 0;
  let n = 0;
  for (let i = dataAt + 8; i + 1 < bytes.length; i += 2) {
    const v = bytes.readInt16LE(i) / 32768;
    sum += v * v;
    n++;
  }
  const rmsDb = 20 * Math.log10(Math.sqrt(sum / n));
  console.log(`exported WAV: ${(bytes.length / 1e6).toFixed(2)} MB, RMS ${rmsDb.toFixed(1)} dBFS`);
  expect(rmsDb).toBeGreaterThan(-45);
  await expect(page.getByText('Your song is ready')).toBeVisible();
});
EOF
