  "title": "Seedsong — demo",
  "voice": "af_heart",
  "speed": 0.94,
  "scenes": [
    {
      "id": "intro",
      "action": "landing",
      "caption": "A recursive function grows a tree. Its call tree becomes the music.",
      "text": "This is Seedsong. A recursive function grows a glowing tree... and the shape of its call tree becomes calm, ambient music."
    },
    {
      "id": "begin",
      "action": "begin",
      "caption": "Every call is a note. Every leaf, the base case, rings a bell. Every return resolves a phrase.",
      "text": "Press Begin. A warm drone fades in, and the trunk grows with a low note. From here, every call is a note. Every leaf, the base case, rings a bell. And every return... resolves the phrase.",
      "hold": 6
    },
    {
      "id": "lens",
      "action": "lens",
      "caption": "The recursion lens: the live call stack and the line of code that is running.",
      "text": "Open the recursion lens to watch it happen, live. The call stack, the current depth, and the exact line of code that's running right now."
    },
    {
      "id": "bloom",
