      #demo-end .tag{font:italic 300 32px 'Fraunces Variable',serif;color:#EEF1F8;margin-top:22px}
      #demo-end .links{margin-top:44px;font:500 22px/1.8 'JetBrains Mono Variable',monospace;color:#F5B38A}
