await page.evaluate(() => {
  const ctx = window.__tapCtx;
  if (!ctx) throw new Error('no audio context tap');
  const rec = new MediaRecorder(ctx.__tap.stream, { mimeType: 'audio/webm;codecs=opus', audioBitsPerSecond: 320000 });
