await scene(S.moods, async ({ cue, after }) => {
  await cue();
  await after(1.6);
  await click(page.getByRole('radio', { name: 'Deep Ocean' }));
  await after(7.2);
  await click(page.getByRole('radio', { name: 'Night Forest' }));
