scenes.forEach((s, i) => {
  s.outStart = i === 0 ? 0 : acc - D;
  acc = i === 0 ? s.L : acc + s.L - D;
});
const total = acc;

const ease = (P) => `if(lt(${P},0.5),4*${P}*${P}*${P},1-pow(-2*${P}+2,3)/2)`;
