import { it } from 'vitest';
import { grove } from './worlds/grove';
import { composeScore } from './music/compose';
import { MOOD_LIST } from './music/moods';
it('stats', () => {
  const t = grove.generate(grove.defaults, 'still-lake-07');
  for (const m of MOOD_LIST) for (const mode of ['wander', 'bloom'] as const) {
    const s = composeScore(t, { moodId: m.id, mode });
    const gaps = s.chords.slice(1).map((c, i) => c.time - s.chords[i].time);
    const att = s.notes.filter((n) => ['lead', 'bell', 'ornament'].includes(n.voice)).length;
    const first = s.notes.filter((n) => n.voice === 'lead' || n.voice === 'bell')[0]?.time ?? -1;
    console.log(`${m.id.padEnd(7)} ${mode.padEnd(7)} ${s.bpm} BPM  ${s.duration.toFixed(0)} s  chords ${s.chords.length} (avg gap ${(gaps.reduce((a, b) => a + b, 0) / gaps.length).toFixed(1)} s)  bass ${s.notes.filter((n) => n.voice === 'bass').length}  notes/s ${(att / s.duration).toFixed(2)}  first melody ${first.toFixed(1)} s`);
  }
});
EOF
